import TextField from '@mui/material/TextField';
import Autocomplete from '@mui/material/Autocomplete';
import React, {useEffect, useState} from 'react';
import { stocks, categories} from '../../models/contants/contants';
import IStockLookup from '../../models/common/lookup';
import ILookup from '../../models/common/lookup';
import { AlertChannelType, AlertStockFilterType, IAlert } from '../../models/alert/alert';
import axios from 'axios';
import { backend } from '../../models/contants/contants';
import toast, { Toaster } from 'react-hot-toast';
import * as utility from '../../utility/utility';
import { useParams } from 'react-router-dom';
import { EmailIcon, SMSIcon, WhatsappIcon } from '../common/utilitycomp';
import { Box, LinearProgress, ThemeProvider } from '@mui/material';
import { muiTheme1 } from '../common/muicomp';

const Alert = () => {
    const [showLoading,setShowLoading] = useState<boolean>(false);
  const params= useParams();
  const [smsChannel, setSMSChannel] = useState("");
  const [whatsappChannel, setWhatsappChannel] = useState("");
  const [emailChannel, setEmailChannel] = useState("");
  const [alert, setAlert] = useState<IAlert>(
    {
      alertKey:'',
      name:'',
      stockFilterType: AlertStockFilterType.stock,
      userId :'test',
      smsChannels: [],
      whatsappChannels:[],
      emailChannels:[],
      stockCodes:[],
      categoryCodes:[]
    });

    const loadAlert = async (alertKey:string) => {
      setShowLoading(true);
              await axios({
                  url: backend+'alerts/'+alertKey+'?userId=test',
                  method: "Get",
                  headers: {
                      authorization: "your token comes here",
                  }
              })
                  .then((res) => {
                      const data: IAlert = res.data;
                      setAlert(data);
                  })
                  .catch((err) => {
                    window.alert('unable to get alert details')
                  }).finally(()=>{
                    setShowLoading(false);
                  });
          }
 // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
      if(params && params["alertkey"]){
        loadAlert(params["alertkey"]);
      }
       // eslint-disable-next-line react-hooks/exhaustive-deps
    },[]);

    const validateSaveAlert = () => {
      var isvalid = true;
      if(utility.isNullEmptyOrWhitespace(alert.name)){
        toast.error('invalid alert name');
        isvalid = false;
      }

      if(alert.stockCodes.length === 0 && alert.categoryCodes.length === 0){
        toast.error('select stocks or categories');
        isvalid = false;
      }

      if(alert.smsChannels.length === 0 && alert.whatsappChannels.length === 0 && alert.emailChannels.length === 0){
        toast.error('select alert notification channels');
        isvalid = false;
      }

      return isvalid;
    }
    const saveAlert = async  (event:any) =>{
      if(!validateSaveAlert()){
        return;
      }
      await axios({
        // Endpoint to send files
        url: backend+"alerts",
        method: "Post",
        headers: {
            // Add any auth token here
            authorization: "your token comes here",
        },

        // Attaching the form data
        data: alert,
    })
        // Handle the response from backend here
        .then((res) => {
          toast.success('alert saved');
            window.location.href = '#/alerts';
        })
        .catch((err) => {});
    }

    const cancelAlert = async  (event:any) =>{
      window.location.href = '#/alerts';
    }
    // const onSectorsChange = (event:any, values:ILookup[]) => {
    //     //setAnnoncementRequest({...annnouncementRequest, stockcodes: values.map(a=> a.code)});
    // } 
    const onFilterStocksChange = (event:any, values:ILookup[]) => {
      setAlert({...alert, stockCodes: values.map(a=> a.code)});
    } 

    const onCategoriesChange = (event:any, values:ILookup[]) => {
        setAlert({...alert, categoryCodes: values.map(a => a.code)});
    } 

    const saveSMSChannel = (event:any) =>{
      if(utility.validatePhoneNum(smsChannel)){
        alert.smsChannels?.push(smsChannel);
        setSMSChannel("");
      }else{
        toast.error('invalid phone number for sms');
      }
    }
      const saveWhatsappChannel = (event:any) =>{
        if(utility.validatePhoneNum(whatsappChannel)){
          alert.whatsappChannels?.push(whatsappChannel);
          setWhatsappChannel("");
        }else{
          toast.error('invalid phone number for whatsapp');
        }
    }
    const saveEmailChannel = (event:any) =>{
      if(utility.validateEmail(emailChannel)){
        alert.emailChannels?.push(emailChannel);
        setEmailChannel("");
      }else{
        toast.error('invalid email');
      }
    }

    const deleteChannel = (channel:string, channelType:AlertChannelType) =>{
     if(channelType === AlertChannelType.sms){
      setAlert({...alert, smsChannels: alert.smsChannels.filter(a => a !== channel)});
     }else if(channelType === AlertChannelType.whatsapp){
      setAlert({...alert, whatsappChannels: alert.whatsappChannels.filter(a => a !== channel)});
     }else if(channelType === AlertChannelType.email){
      setAlert({...alert, emailChannels: alert.emailChannels.filter(a => a !== channel)});
     }
    }

    const AlertChannelRow = (props:any) => (
      <tr>
          <td>{props.channel}</td>
          <td>
            {props.type === AlertChannelType.sms && <SMSIcon/>}
            {props.type === AlertChannelType.whatsapp && <WhatsappIcon/>}
            {props.type === AlertChannelType.email && <EmailIcon/>}
             &nbsp;&nbsp;{props.type}</td>
          <td>
          <button onClick={() => deleteChannel(props.channel,props.type)} className="btn btn-link text-danger text-gradient px-3 mb-0">
          <i className="material-symbols-rounded text-sm me-2">delete</i>Delete</button>
          </td>
        </tr>
    )

    const getPageHeader = () =>{
      if(params["alertkey"]){
return "Edit Alert"
      }else{
return "Create Alert"
      }
    }

    return (
      <div>
        <Toaster position="bottom-center" reverseOrder={false}/>
        <div className="card border-0 rounded-0 shadow-none">
        <div className="card-header">
        <ol className="breadcrumb bg-transparent mb-0 pb-0 pt-1 px-0 me-sm-6 me-5">
              <li className="breadcrumb-item"><a className='text-secondary' href="#/alerts">
              <i className="material-symbols-rounded opacity-5 text-sm ">table_view</i> 
              &nbsp; Alerts</a></li>
              <li className="breadcrumb-item text-dark active" aria-current="page"><strong>
                <span>{getPageHeader()}</span></strong></li>
                </ol>
            </div>
            {showLoading && <Box  sx={{width: '100%' }}> <LinearProgress /></Box>} 

 { !showLoading && <ThemeProvider theme={muiTheme1}>
    <div className="card-body">
    <div className='row'>
        <div className='col mb-3'>
        <TextField size='small'
         value={alert.name} 
         onChange={(e) =>{
           setAlert({...alert, name: e.target.value});
          }
        }
        id="outlined-basic" label="alert name" 
        variant="outlined" />
        </div>
  </div>
    <div className="form-floating mb-3">
    <Autocomplete  size='small'
      value={stocks.filter(a => alert.stockCodes.filter(b => b === a.code).length > 0)}
      onChange={onFilterStocksChange}
      multiple
      options={stocks}
      getOptionLabel={(option:IStockLookup) => option.code+' - '+option.name}
      renderInput={(params) => (
        <TextField {...params} label="filter stocks" placeholder="Search by scrip code or name" />
      )}
    />
</div>

<div className="row mb-3">
  <Autocomplete size='small'
      value={categories.filter(a => alert.categoryCodes.filter(b => b === a.code).length > 0)}
      multiple
      id=""
      onChange={onCategoriesChange}
      options={categories}
      getOptionLabel={(option:ILookup) => option.name}
      renderInput={(params) => (
        <TextField {...params} label="category" placeholder="Select Categories" />
      )}
    />
</div>
<div className="card">
        <div className="card-header pb-0 p-3">
              <div className="row mb-3">
              <div className="col-6 d-flex align-items-center">
                  <h6 className="mb-0">Alerting Channels</h6>
                </div>
                <div className="col-6 text-end">
                <button className="collapsed btn bg-gradient-light btn-sm mb-0" 
                  data-bs-target="#channelsAddAccordin" aria-controls="channelsAddAccordin"
                   data-bs-toggle="collapse" data-bs-auto-close="outside" aria-expanded="false">Add Channels&nbsp;
                   <span className="hide material-symbols-rounded">arrow_drop_up</span>
                    <span className="collapseshow material-symbols-rounded">arrow_drop_down</span>
                   </button>
                </div>
              </div>
            </div>

            <div className='accordion-item'>
              <div id="channelsAddAccordin"  className="accordion-collapse collapse show" data-bs-parent="#accordionExample">
              <div className='accordion-body card'>
              <div className='row align-items-center mb-2'>
              <div className='col'>
            

              <TextField size='small' value={smsChannel} onChange={(e) => {setSMSChannel(e.target.value)}} id="txtSMSChannel" label="add phone number with country code" variant="outlined" />
              </div>
              <div className='col'>
              <button onClick={saveSMSChannel} className="btn bg-gradient-light mb-0 ml-5 btn-sm">
              <SMSIcon/>&nbsp;Add SMS channel</button>
              </div>
            </div>
            <div className='row align-items-center mb-2'>
              <div className='col'>
              <TextField size='small' value={whatsappChannel} onChange={(e) => {setWhatsappChannel(e.target.value)}} id="txtWhatsappChannel" label="add whatsapp phone number with country code" variant="outlined" />
              </div>
              <div className='col align-items-center'>
              <button onClick={saveWhatsappChannel}  className="btn bg-gradient-light mb-0 ml-5 btn-sm">
                <WhatsappIcon/>
              &nbsp;Add Whatsapp channel</button>
              </div>
            </div>
            <div className='row align-items-center mb-2'>
              <div className='col'>
              <TextField size='small' value={emailChannel} onChange={(e) => {setEmailChannel(e.target.value)}} id="txtEmailChannel" label="add email channel" variant="outlined" />
              </div>
              <div className='col align-items-center'>
                  <button onClick={saveEmailChannel} className="btn bg-gradient-light mb-0 ml-5 btn-sm">
                  <EmailIcon/>&nbsp; Add Email</button>
              </div>
            </div>
            </div>
                </div>
                </div>

            <div className="card-body ">
{(alert.smsChannels?.length > 0 || alert.whatsappChannels?.length > 0 || alert.emailChannels?.length > 0) && <div className="card-body table-responsive px-0 pb-2">
  <table className="table align-items-center mb-0">
    <thead>
      <tr>
        <th>
        <div className='text-uppercase text-secondary text-xxs font-weight-bolder opacity-7'>Channel</div>
        </th>
        <th>
        <div className='text-uppercase text-secondary text-xxs font-weight-bolder opacity-7'>Channel type</div>
        </th>
        <th>
        <div className='text-uppercase text-secondary text-xxs font-weight-bolder opacity-7'>Delete</div>
        </th>
      </tr>
    </thead>
    <tbody>
    {alert.smsChannels?.map(( listValue:string ) => {return <AlertChannelRow channel={listValue} type={AlertChannelType.sms}/>})}
   {alert.whatsappChannels?.map(( listValue:string ) => {return <AlertChannelRow channel={listValue} type={AlertChannelType.whatsapp}/>})}
  {alert.emailChannels?.map(( listValue:string ) => {return <AlertChannelRow channel={listValue} type={AlertChannelType.email}/>})}
    </tbody>
  </table>
</div>}
</div>
            
        </div>
<div className="text-right pt-3">
<button type='button' onClick={saveAlert} className="btn bg-gradient-light btn-sm mb-0 mr-2 ">
<span className="material-symbols-rounded text-sm  text-success">
check
</span>
&nbsp;Save</button>
<button type='button' onClick={cancelAlert} className="btn bg-gradient-light btn-sm mb-0 ml-7">
<span className="material-symbols-rounded text-sm  text-danger">
close
</span>
&nbsp;Cancel</button>
</div>
      
    </div>
    </ThemeProvider>}
        </div>
        </div>
    ) 
}

export default Alert;


