import React, {useEffect, useState} from 'react';
import axios from 'axios';
import { backend, categories } from '../../models/contants/contants';
import { useNavigate, useParams } from 'react-router-dom';
import IAnnouncement from '../../models/announcement/announcement';
import dayjs from 'dayjs';
import AnnouncementsComp from './announcementComp';
import { Box, LinearProgress } from '@mui/material';
import { ImpressionBadge } from '../common/utilitycomp';

const Announcement = () => {
  const params= useParams();
   const [showLoading,setShowLoading] = useState<boolean>(false);
  const [announcement, setAnnoncement] = useState<IAnnouncement|undefined>(
    undefined);

    const loadAnnouncement = async (announcementKey:string) => {
      setShowLoading(true);
              await axios({
                  url: backend+'announcements/'+announcementKey,
                  method: "Get",
                  headers: {
                      authorization: "your token comes here",
                  }
              })
                  .then((res) => {
                      const data: IAnnouncement = res.data;
                      setAnnoncement(data);
                  })
                  .catch((err) => {
                    //window.alert('unable to get alert details')
                  }).finally(()=>{
                    setShowLoading(false);
                  });
          }
 // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
      window.scrollTo(0, 0);
      if(params && params["announcementKey"]){
        loadAnnouncement(params["announcementKey"]);
      }
       // eslint-disable-next-line react-hooks/exhaustive-deps
    },[params]);

    const headerName = announcement?.stockCode+"'s Other Announcements";
    const navigate = useNavigate();
    return (
      <div>
       { announcement && <div className="card border-0 rounded-0 shadow-none">
            <div className="card-header"> 
            <ol className="breadcrumb bg-transparent mb-0 pb-0 pt-1 px-0 me-sm-6 me-5">
              <li className="breadcrumb-item"><a className='text-secondary' href="#/announcements">
              <i className="material-symbols-rounded opacity-5 text-sm">table_view</i> 
              &nbsp; Annoucements</a></li>
              <li className="breadcrumb-item text-dark active" aria-current="page"><strong>
                <span>{announcement.stockName}</span></strong></li></ol>
            </div>
           {showLoading && <Box  sx={{width: '100%' }}> <LinearProgress /></Box>} 

                <div className="card-body p-3">
                  <ul className="list-group mb-3">
                  <li className="list-group-item border-0 ps-0">
                    <strong className="text-dark">Company:</strong> &nbsp; {announcement.stockName} (#{announcement.stockCode})</li>
                    <li className="list-group-item border-0 ps-0">
                    <strong className="text-dark">Category:</strong> &nbsp; {categories.filter(a => a.code === announcement.category)[0].name}</li>
                    <li className="list-group-item border-0 ps-0">
                    <strong className="text-dark">Summary:</strong> &nbsp; {announcement.aiSummary ?? announcement.subject}</li>
                 
                    <li className="list-group-item border-0 ps-0"><strong className="text-dark">Announcement Date:</strong> &nbsp; {dayjs(announcement.announcementDate).format("MMM D, YYYY h:mm A")}</li>
                    <li className="list-group-item border-0 ps-0"><strong className="text-dark">Exchange:</strong> &nbsp; {announcement.source}</li>
                    <li className="list-group-item border-0 ps-0">
                      <strong className="text-dark">Announcement PDF:</strong> &nbsp; <a className="url" target='blank' href={announcement.url}>
                      Announcement URL <i className="material-symbols-rounded me-2">open_in_new</i></a></li>
                    <li className="list-group-item border-0 ps-0"><strong className="text-dark">Impression:</strong> &nbsp; 
                    {ImpressionBadge(announcement.impression)}
                    </li>
                  </ul>
                  <AnnouncementsComp announcementKey={params["announcementKey"]} headerName={headerName} filterbyStock={announcement.stockCode} isCard={true}></AnnouncementsComp>
            </div>
      </div>
      }
</div>

)}

export default Announcement;
