import React, {useEffect, useState} from 'react';
import { Box, LinearProgress } from '@mui/material';
import AlertTable from './alertTable';
import { useNavigate } from 'react-router-dom';
import { IAlert, IAlertTable } from '../../models/alert/alert';
import axios from 'axios';
import { backend } from '../../models/contants/contants';
import { Toaster } from 'react-hot-toast';

const Alerts = () => {
    const navigate = useNavigate();
    const [showLoading,setShowLoading] = useState<boolean>(false);
    const [userAlerts, setUserAlerts] = useState<IAlert[]>([]);

    const loadUserAlerts = async () => {
        setShowLoading(true);
        await axios({
            // Endpoint to send files
            url: backend+"alerts?userId=test",
            method: "Get",
            headers: {
                // Add any auth token here
                authorization: "your token comes here",
            }
        })
            // Handle the response from backend here
            .then((res) => {
                const data: IAlert[] = res.data;
                //setUserAlerts(mapToAlertsTable([...data]));
                setUserAlerts(data);
                setShowLoading(false);
            })
            .catch((err) => {});
    }

    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
        loadUserAlerts();
         // eslint-disable-next-line react-hooks/exhaustive-deps
    },[] );

    const gotoAlert = async () => {
        navigate('/alert');
    }
    return (
        <div>
         <Toaster position="bottom-center" reverseOrder={false}/>
        <div className="card border-0 rounded-0 shadow-none">
        <div className="card-header">
              <div className="row">
                <div className="col-6 d-flex align-items-center">
                  <h6 className="mb-0">Alerts</h6>
                </div>
                <div className="col-6 text-end">
                <button onClick={gotoAlert} className="btn bg-gradient-light btn-sm mb-0">
                    <i className="material-symbols-rounded text-sm">add</i>&nbsp;&nbsp;Add New Alert</button>
                </div>
              </div>
            </div>
<div className="card-body p-0">
{ showLoading && <Box  sx={{width: '100%' }}> <LinearProgress /></Box>}
<div className="table-responsive">
            { userAlerts?.length > 0 && 
              <AlertTable rows={userAlerts}/>}
</div>
</div>

        </div>
        </div>
    )
}

export default Alerts;
