import React, {useEffect, useState} from 'react';
import { Box, LinearProgress } from '@mui/material';
import axios from 'axios';
import { backend } from '../../models/contants/contants';
import { Toaster } from 'react-hot-toast';
import { INotification, NotificationType } from '../../models/notification/notification';
import { formatRecentTime } from '../../utility/utility';
import { useNavigate } from 'react-router-dom';

const Notifications = () => {
    var d = new Date();
    d.setMinutes(d.getMinutes() - 100);

    var d1 = new Date();
    d1.setDate(d1.getDate() - 11);


    const [showLoading,setShowLoading] = useState<boolean>(false);
    const [notitications, setNotifications] = useState<INotification[]>([{
        isRead: false,
        notification: 'Your alert has triggered for WABAG announcement view link',
        date: d,      
        notificationKey: '1111',
        type: NotificationType.alerttrigger,
        alerttrigger_announcementKey: '58OvK3CC2lO7L15C4Yjd'
    },
    {
        
        isRead: false,
        notification: 'Test not',
        date: d1,      
        notificationKey: '2222',
        type: NotificationType.alerttrigger
    },
    {
        
        isRead: false,
        notification: 'Test not',
        date: new Date(),
        notificationKey: '3333',
        type: NotificationType.alerttrigger
    },
    {
        
        isRead: false,
        notification: 'Test not',
        date: new Date(),
        notificationKey: '444',
        type: NotificationType.alerttrigger
    },
    {
        
        isRead: true,
        notification: 'Test not',
        date: new Date(),
        notificationKey: '444',
        type: NotificationType.alerttrigger
    },
    {
        
        isRead: false,
        notification: 'Test not',
        date: new Date(),
        notificationKey: '44',
        type: NotificationType.alerttrigger
    },
    {
        
        isRead: false,
        notification: 'Test not',
        date: new Date(),
        notificationKey: 'd',
        type: NotificationType.alerttrigger
    }]);

    const loadUserAlerts = async (page:number,limit:number) => {
        setShowLoading(true);
        await axios({
            // Endpoint to send files
            url: backend+"notifications?page="+page+"&limit="+limit,
            method: "Get",
            headers: {
                // Add any auth token here
                authorization: "your token comes here",
            }
        })
            // Handle the response from backend here
            .then((res) => {
                const data: INotification[] = res.data;
                setNotifications(data);
                setShowLoading(false);
            })
            .catch((err) => {setShowLoading(false)});
    }

    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
        loadUserAlerts(0,100);
         // eslint-disable-next-line react-hooks/exhaustive-deps
    },[] );

    const markAllAsRead = async () => {
        setNotifications(n => 
            n.map(n => ({ ...n, isRead: true }))
          );
        await axios({
            // Endpoint to send files
            url: backend+"notifications/markasread",
            method: "Post",
            headers: {
                // Add any auth token here
                authorization: "your token comes here",
            }
        })
            // Handle the response from backend here
            .then((res) => {
                
            })
            .catch((err) => {});
    }

    const onMarkAsRead = async (e:any,notificationKey:string) => {
        markAsRead(notificationKey);
        e.stopPropagation();
    }

    const markAsRead = async (notificationKey:string) =>{
        setNotifications(notitications.map(n => 
            n.notificationKey === notificationKey ? { ...n, isRead:true } : n
          ));

          await axios({
            // Endpoint to send files
            url: backend+"notifications/"+notificationKey+"/markasread",
            method: "Post",
            headers: {
                // Add any auth token here
                authorization: "your token comes here",
            }
        })
            // Handle the response from backend here
            .then((res) => {
                
            })
            .catch((err) => {});
    }
    const navigate = useNavigate();
    const onNotificationClick = (notification:INotification) =>{
        markAsRead(notification.notificationKey);
        if(notification.type === NotificationType.alerttrigger)
        navigate("/announcements/"+notification.alerttrigger_announcementKey);
    }
    return (
        <div>
          <Toaster position="top-center" reverseOrder={true}/>
        <div className="card border-0 rounded-0 shadow-none">
        <div className="card-header">
              <div className="row">
                <div className="col-6 d-flex align-items-center">
                  <h6 className="mb-0">Notifications</h6>
                </div>
                <div className="col-6 text-end">
                <button onClick={markAllAsRead} className="btn bg-gradient-light mb-0 ml-5 btn-sm">
                Mark all read</button>
                </div>
              </div>
            </div>
<div className="card-body p-0">
{ showLoading && <Box  sx={{width: '100%' }}> <LinearProgress /></Box>}

<ul style={{listStyle:'none', paddingLeft:0}}>
           {
             notitications.map(notification => 
                
                <li className="bb-1 li-1">
                  <div onClick={() =>onNotificationClick(notification)}  className="row notificatindiv">
                    <div className="col-md-8 d-flex align-items-center ">
                    <div className="d-flex py-1">
                        <div className="d-flex flex-column justify-content-center">
                            <div className={(!notification.isRead ? 'font-weight-bold text-dark':'')+' text-sm mb-1 '}>
                                 {
                                    notification.notification
                                }</div>
                                <p className="text-xs text-secondary mb-0">
                                   
                                    {formatRecentTime(notification.date)}</p></div>
                                    </div>
                                    </div>
                                   { !notification.isRead && <div className="col-md-4 text-end">
                                        <button onClick={(e) => onMarkAsRead(e,notification.notificationKey)} 
                                        className="btn btn-link text-sm text-secondary mb-0 font-weight-bold">mark as read
                                            </button>
                                            </div>}
                                            </div>
                </li>
             )
           }
           </ul>
           <div style={{textAlign:'center'}}>
           {/* 
           TODO: implement view more
           <button className="btn bg-gradient-light btn-sm mb-0 text-center">
           view more</button> */}
           </div>
           
</div>

        </div>
        </div>
    )
}

export default Notifications;
