import { Outlet } from 'react-router';
import React, { useState } from 'react';

export const Header = () => {
    const toggleSideMenu = (e:any) =>{
        if(document.body.classList.contains('g-sidenav-pinned'))
            document.body.classList.remove('g-sidenav-pinned');
        else
            document.body.classList.add('g-sidenav-pinned');
       e.preventDefault();
}
    return <>

<nav className="navbar navbar-expand-lg navbar-light bg-light shadow-none">
    <a className="navbar-brand" href="#">
      <img width="80" height="26" className="navbar-brand-img"  alt="img" src="https://t3.ftcdn.net/jpg/11/13/90/68/240_F_1113906868_2pzj3wzhBZ0wfm0WUypuJP69FcrHZgMc.jpg"/>
    </a>

    <a onClick={(e)=>toggleSideMenu(e)} href="javascript:;" className="nav-link text-body d-xl-none" 
    id="icddonNavbarSidenav">
      <div className="sidenav-toggler-inner">
        <i className="sidenav-toggler-line"></i>
        <i className="sidenav-toggler-line"></i>
        <i className="sidenav-toggler-line"></i>
      </div>
    </a>
    <div className="collapse navbar-collapse" id="navbarTogglerDemo02">
      <ul className="navbar-nav mr-auto mt-2 mt-lg-0">
        <li className="nav-item dropdown d-flex align-items-center">
          <a href="#/signin" className="nav-link text-body font-weight-bold">
            Hie, Guest &nbsp;<i className="va-sub material-symbols-rounded">account_circle</i>
          </a>
        </li>
      </ul>
    </div>
  </nav>
  
    </>;
}
export default Header;
